class ApiError extends Error{constructor(status,data){super(data?.message||'Request failed');this.status=status;this.code=data?.code||data?.error;this.data=data;}}
function errorText(error){
  if(error instanceof ApiError&&error.code?.startsWith('voucher_')){const key=({voucher_not_ready:'voucherUnavailable',voucher_not_paid:'voucherUnavailable',voucher_unavailable:'voucherUnavailable',voucher_balance:'voucherBalanceChanged',voucher_insufficient_balance:'voucherBalanceChanged',voucher_invalid_amount:'voucherInvalidAmount',voucher_amount_invalid:'voucherInvalidAmount',voucher_idempotency_conflict:'voucherConflict',voucher_reservation_missing:'voucherReservationChanged',voucher_reservation_not_active:'voucherReservationChanged',voucher_refund_not_allowed:'voucherRefundBlocked',voucher_not_refundable:'voucherRefundBlocked',voucher_migration_required:'voucherConfigMissing',voucher_schema_unavailable:'voucherConfigMissing',voucher_mail_failed:'voucherMailPending'})[error.code];if(key)return tr(key);}
  if(error instanceof ApiError){const requiredErrors={image_files_expired:'orderFilesExpired',image_ordered:'imageOrderedError',final_confirmation_required:'finalMarkConfirmationMissing',invalid_selection:'finalMarkChanged',image_changed:'finalFileChanged',watermark_changed:'finalWatermarkChanged',protected_preview_required:'finalWatermarkChanged',test_order_not_eligible:'deleteTestOrderUnavailable',package_order_changed:'packageOrderChanged',invalid_activity_before:'activityReadInvalid',final_delivery_not_enabled:'finalModeRequired',final_delivery_required:'finalModeRequired',invalid_activity_cutoff:'activityReadInvalid',activity_read_invalid:'activityReadInvalid',test_order_confirmation_required:'deleteTestOrderMismatch',order_delete_confirmation_required:'deleteTestOrderMismatch',order_cannot_delete:'deleteTestOrderUnavailable',test_order_delete_not_allowed:'deleteTestOrderUnavailable',order_deletion_not_ready:'deleteTestOrderMigration',package_order_not_ready:'packageOrderMigration',invalid_package_order:'packageOrderChanged',package_set_changed:'packageOrderChanged',order_cannot_cancel:'pendingOrderCannotCancel',order_cancel_confirmation_required:'cancelPendingOrderConfirm',invalid_required_package:'packageRequiredActiveOnly',required_package_pending:'packageRequiredPending',required_package_processing:'packageRequiredProcessing',required_package_missing:'packageRequiredCheckoutHint',required_package_paid:'packageRequiredPaidHint',deletion_confirmation_required:'deleteGalleryNameMismatch',gallery_changed:'deleteGalleryChanged'};if(requiredErrors[error.code])return tr(requiredErrors[error.code]);if(['price_changed','package_not_found','package_image_count','package_selection_unavailable','invalid_pricing_mode'].includes(error.code))return tr('packagePriceChanged');if(['image_in_order','image_ordered'].includes(error.code))return tr('imageInOrder');if(error.status===401)return tr(error.code==='invalid_credentials'?'errorAuth':'errorSession');if(error.status===403)return tr('errorForbidden');if(error.status===404||error.status===410)return tr('errorNotFound');if(error.status===429)return tr('errorRate');if(error.status===503||error.code?.includes?.('configured'))return tr('errorConfig');}
  if(error?.message?.startsWith('UI:'))return error.message.slice(3);
  return tr('errorGeneric');
}
async function api(path,options={}){
  const method=options.method||'GET',headers={Accept:'application/json',...options.headers};
  if(state.csrf&&method!=='GET')headers['X-CSRF-Token']=state.csrf;
  let body=options.body;
  if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body);}
  const response=await fetch('/api'+path,{...options,method,headers,body,credentials:'same-origin',cache:'no-store'});
  let data;try{data=await response.json();}catch{throw new ApiError(response.status||503,{error:'connection_unavailable'});}
  if(!response.ok)throw new ApiError(response.status,data);
  return data;
}
let toastTimer;
function toast(message){const node=document.querySelector('#portal-toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5000);}
function message(form,text,type='error'){let node=form.querySelector('.portal-form-message');if(!node){node=document.createElement('p');node.className='portal-form-message portal-message';node.setAttribute('role','status');form.append(node);}node.className='portal-form-message portal-message '+type;node.textContent=text;}
async function withBusy(form,fn){const buttons=[...form.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);form.setAttribute('aria-busy','true');try{await fn();}catch(error){message(form,errorText(error));}finally{if(form.isConnected){buttons.forEach(b=>b.disabled=false);form.removeAttribute('aria-busy');if(form.id==='portal-order-form')updateCheckoutSummary();if(form.id==='portal-delete-gallery')buttons.forEach(b=>b.disabled=form.elements.confirmName.value!==state.deleteGalleryTarget?.name);if(form.id.startsWith('portal-delete-test-order'))syncDeleteTestOrderConfirmation(form);if(form.id==='portal-final-batch')renderFinalBatchReview();}}}
let fieldCounter=0;
function field(label,name,type='text',value='',attrs=''){const id=`p-${name}-${++fieldCounter}`;return `<div class="portal-field"><label for="${id}">${esc(label)}</label><input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function passwordField(label,name,attrs=''){return `<div class="portal-field"><label for="p-${name}">${esc(label)}</label><div class="portal-password"><input id="p-${name}" name="${name}" type="password" ${attrs}><button type="button" data-action="show-password" data-input="p-${name}" aria-label="${esc(tr('showPassword'))}" aria-pressed="false">${icon('eye')}</button></div></div>`;}
const themeOptions={warm:'themeWarm',light:'themeLight',dark:'themeDark',cream:'themeCream',rose:'themeRose',blush:'themeBlush',sand:'themeSand',clay:'themeClay',sage:'themeSage',olive:'themeOlive',forest:'themeForest',sea:'themeSea',sky:'themeSky',lavender:'themeLavender',slate:'themeSlate'};
const coverLayoutOptions={overlay:'coverOverlay',split:'coverSplit',editorial:'coverEditorial','split-reverse':'coverSplitReverse',card:'coverCard',arch:'coverArch',polaroid:'coverPolaroid',minimal:'coverMinimal'};
const coverDecorationOptions={none:'decorationNone',frame:'decorationFrame',stripe:'decorationStripe','double-frame':'decorationDoubleFrame',corners:'decorationCorners',underline:'decorationUnderline','soft-shadow':'decorationShadow',rounded:'decorationRounded'};
const coverHeightOptions={compact:'heightCompact',standard:'heightStandard',large:'heightLarge'};
const coverFitOptions={contain:'coverFitContain',cover:'coverFitCover'};
function setView(html){app.innerHTML=html;app.removeAttribute('aria-busy');document.querySelector('.portal-content').dataset.theme=state.view==='gallery'&&Object.hasOwn(themeOptions,state.detail?.gallery.theme)?state.detail.gallery.theme:'warm';}
const shootingTypes={school:'typeSchool',maternity:'typeMaternity',newborn:'typeNewborn',family:'typeFamily',portrait:'typePortrait',wedding:'typeWedding',combo:'typeCombo',other:'typeOther'};
function selectField(label,name,options,value){const id=`p-${name}-${++fieldCounter}`;return `<div class="portal-field"><label for="${id}">${esc(label)}</label><select id="${id}" name="${name}">${Object.entries(options).map(([option,key])=>`<option value="${option}" ${option===value?'selected':''}>${esc(tr(key))}</option>`).join('')}</select></div>`;}
function paletteField(theme='warm'){
  const choices=`<div class="portal-theme-options" role="group" aria-label="${esc(tr('theme'))}">${Object.entries(themeOptions).map(([value,label])=>`<button type="button" class="portal-theme-option" data-action="choose-theme" data-theme="${value}" aria-pressed="${value===theme}" aria-label="${esc(tr(label))}"><span class="portal-palette-swatches" aria-hidden="true"><i></i><i></i><i></i></span><span>${esc(tr(label))}</span></button>`).join('')}</div>`;
  return selectField(tr('theme'),'theme',themeOptions,theme).replace('</select>',`</select>${choices}`);
}
function galleryControls(gallery={},appearance=false){
  const basic=selectField(tr('shootingType'),'shootingType',shootingTypes,gallery.shootingType||'other')+selectField(tr('pricingMode'),'pricingMode',{gallery:'modeGallery',images:'modeImages'},gallery.pricingMode||'gallery');
  if(!appearance)return basic;
  return basic+paletteField(gallery.theme||'warm')
    +selectField(tr('gridLayout'),'gridLayout',{masonry:'layoutMasonry',grid:'layoutGrid'},gallery.gridLayout||'masonry')
    +selectField(tr('coverLayout'),'coverLayout',coverLayoutOptions,gallery.coverLayout||'overlay')
    +selectField(tr('coverHeightDesktop'),'coverHeight',coverHeightOptions,gallery.coverHeight||'standard')
    +selectField(tr('coverHeightMobile'),'coverHeightMobile',coverHeightOptions,gallery.coverHeightMobile||'standard')
    +selectField(tr('coverFitDesktop'),'coverFit',coverFitOptions,gallery.coverFit||'contain')
    +selectField(tr('coverFitMobile'),'coverFitMobile',coverFitOptions,gallery.coverFitMobile||'cover')
    +field(tr('coverPosition'),'coverPosition','number',gallery.coverPosition??50,'required min="0" max="100" step="1"')
    +selectField(tr('gridDensity'),'gridDensity',{comfortable:'densityComfortable',compact:'densityCompact',spacious:'densitySpacious'},gallery.gridDensity||'comfortable')
    +field(tr('gridGap'),'gridGap','number',gallery.gridGap??16,'required min="8" max="40" step="1"')
    +`<div class="portal-field"><label class="portal-check"><input type="checkbox" name="showFilenames" ${gallery.showFilenames?'checked':''}><span>${esc(tr('showFilenames'))}</span></label></div>`;
}
function hasGalleryRetention(gallery){return gallery?.retention?.policy==='school-v1';}
function retentionDate(value){const date=new Date(value);return value&&!Number.isNaN(date.valueOf())?new Intl.DateTimeFormat(locale,{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Vienna'}).format(date):'';}
function retentionIntroHtml(){return `<strong>${esc(tr('retentionTitle'))}</strong><ul><li>${esc(tr('retentionCreateGallery'))}</li><li>${esc(tr('retentionCreateUnbought'))}</li><li>${esc(tr('retentionCreatePurchased'))}</li></ul>`;}
function galleryRetentionHtml(gallery){
  if(!hasGalleryRetention(gallery))return field(tr('expiry'),'expiresAt','date',gallery.expiresAt?.slice(0,10)||'');
  const policy=gallery.retention,started=retentionDate(policy.startedAt),closes=retentionDate(policy.closesAt),unbought=retentionDate(policy.unboughtDeleteAt);
  return `<div class="portal-field wide portal-retention-note" data-gallery-retention><strong>${esc(tr('retentionTitle'))}</strong>${started?`<p class="portal-small">${esc(tr('retentionStarted',{date:started}))}</p><dl><div><dt>${esc(tr('retentionGalleryCloses'))}</dt><dd>${esc(closes)}</dd></div><div><dt>${esc(tr('retentionUnboughtDeadline'))}</dt><dd>${esc(unbought)}</dd></div></dl>${new Date(policy.closesAt).valueOf()<=Date.now()?`<p class="portal-small">${esc(tr('retentionGalleryClosed'))}</p>`:''}`:`<p>${esc(tr('retentionDraft'))}</p><ul><li>${esc(tr('retentionCreateGallery'))}</li><li>${esc(tr('retentionCreateUnbought'))}</li></ul>`}<p>${esc(tr('retentionCreatePurchased'))}</p><p class="portal-small">${esc(tr('retentionStorageOnly'))}</p><p class="portal-small">${esc(tr('retentionPendingProtected'))}</p></div>`;
}
function applyCoverAppearance(node,values){
  const choose=(options,value,fallback)=>Object.hasOwn(options,value)?value:fallback;
  Object.assign(node.dataset,{layout:choose(coverLayoutOptions,values.coverLayout,'overlay'),decoration:choose(coverDecorationOptions,values.coverDecoration,'none'),typography:['serif','sans','editorial'].includes(values.typography)?values.typography:'serif',height:choose(coverHeightOptions,values.coverHeight,'standard'),mobileHeight:choose(coverHeightOptions,values.coverHeightMobile,'standard'),fit:choose(coverFitOptions,values.coverFit,'contain'),mobileFit:choose(coverFitOptions,values.coverFitMobile,'cover')});
  const photo=node.querySelector(':scope > img');if(photo)photo.style.objectPosition=`50% ${Math.max(0,Math.min(100,Number(values.coverPosition??50)))}%`;
}
