  return `<section class="portal-card portal-login-card" aria-labelledby="portal-auth-title"><h2 id="portal-auth-title">${esc(heading)}</h2><p>${esc(tr(mode==='login'?'loginIntro':mode==='setup'?'setupIntro':'resetIntro'))}</p><div class="portal-tabs" role="tablist" aria-label="${esc(tr('security'))}"><button type="button" role="tab" aria-selected="${mode==='login'}" data-action="auth-mode" data-mode="login">${esc(tr('login'))}</button><button type="button" role="tab" aria-selected="${mode!=='login'}" data-action="auth-mode" data-mode="setup">${esc(tr('setup'))}</button></div><form id="portal-login-form">${field(tr('email'),'email','email','',`autocomplete="email" required maxlength="254"`)}${mode==='login'?passwordField(tr('password'),'password','autocomplete="current-password" required'):''}<button type="submit" class="portal-btn block">${esc(tr(mode==='login'?'login':mode==='setup'?'requestSetup':'requestReset'))}${icon(mode==='login'?'arrow':'mail')}</button><div class="portal-underform">${mode==='login'?`<button type="button" class="portal-link-btn" data-action="auth-mode" data-mode="reset">${esc(tr('forgot'))}</button>`:`<button type="button" class="portal-link-btn" data-action="auth-mode" data-mode="login">${esc(tr('login'))}</button>`}<a class="portal-small" href="mailto:info@liza-memories-photography.com">${esc(tr('help'))}</a></div></form><p class="portal-secure-note">${icon('lock')}<span>${esc(tr('secureNote'))}</span></p></section>`;
