function openLightbox(id){state.lightboxList=visibleImages();state.lightboxIndex=state.lightboxList.findIndex(image=>image.id===id);if(state.lightboxIndex<0)return;const dialog=createDialog(`<div class="portal-lightbox-header"><p id="p-dialog-title"></p><div class="portal-lightbox-actions"><button type="button" class="portal-icon-btn portal-fav" data-action="lightbox-favorite" aria-label="${esc(tr('favoriteAdd'))}" aria-pressed="false">${icon('heart')}</button><button type="button" class="portal-icon-btn" data-action="fullscreen" aria-label="${esc(tr('fullscreen'))}">${icon('fullscreen')}</button><button type="button" class="portal-icon-btn" data-action="close-dialog" aria-label="${esc(tr('close'))}">${icon('close')}</button></div></div><button type="button" class="portal-lightbox-nav prev" data-action="previous" aria-label="${esc(tr('previous'))}">${icon('back')}</button><div class="portal-lightbox-stage"><span class="portal-spinner" aria-hidden="true"></span><img id="p-lightbox-image" alt=""><p class="portal-message error" id="p-lightbox-error" hidden></p></div><button type="button" class="portal-lightbox-nav next" data-action="next" aria-label="${esc(tr('next'))}">${icon('arrow')}</button><div class="portal-lightbox-caption"><p id="p-lightbox-caption"></p><span id="p-lightbox-position"></span> · <button type="button" data-action="lightbox-select" id="p-lightbox-select">${esc(tr('selectPhoto'))}</button></div>`,'portal-lightbox');let startX=0,startY=0;dialog.addEventListener('pointerdown',event=>{if(event.target.tagName==='IMG'){startX=event.clientX;startY=event.clientY;}});dialog.addEventListener('pointerup',event=>{if(event.target.tagName==='IMG'){const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.abs(dx)>55&&Math.abs(dy)<80)moveLightbox(dx<0?1:-1);}});syncLightbox(true);}
