async function makePreview(file,settings=state.adminDetail?.previewSettings){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('UI:'+tr('uploadType'));
  if(file.size>30*1024*1024)throw new Error('UI:'+tr('uploadSize'));
  const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});
  const encode=canvas=>new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('Preview failed')),'image/webp',canvas.dataset.protected?0.65:0.85));
  try{
    if(bitmap.width*bitmap.height>50000000)throw new Error('UI:'+tr('uploadPixels'));
    const makeCanvas=longEdge=>{const ratio=Math.min(1,longEdge/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas;};
    const clean=makeCanvas(1800),blob=await encode(clean);let protectedBlob=null;
    if(settings?.enabled){const canvas=makeCanvas(1200);canvas.dataset.protected='true';paintWatermark(canvas,settings);protectedBlob=await encode(canvas);}
    return{blob,protectedBlob,width:bitmap.width,height:bitmap.height,fingerprint:settings?.fingerprint||''};
  }finally{bitmap.close();}
}
function paintWatermark(canvas,settings){
  const ctx=canvas.getContext('2d'),width=canvas.width,height=canvas.height,text=String(settings.text||'LiZa Memories Photography').slice(0,100),scale=Math.max(width,height)/1200;
  let size=Math.max(12,Math.min(96,Number(settings.size)||36))*scale;ctx.font=`600 ${size}px Arial,sans-serif`;
  const maxWidth=Math.min(width*.82,Math.hypot(width,height)*.72),measured=ctx.measureText(text).width;if(measured>maxWidth)size*=maxWidth/measured;
  ctx.save();ctx.font=`600 ${Math.max(7,size)}px Arial,sans-serif`;ctx.globalAlpha=Math.max(.1,Math.min(1,Number(settings.opacity)||.35));ctx.fillStyle='#ffffff';ctx.strokeStyle='#000000';ctx.lineWidth=Math.max(.6,size/35);ctx.textAlign='center';ctx.textBaseline='middle';
  const draw=(x,y)=>{ctx.strokeText(text,x,y);ctx.fillText(text,x,y);};
  if(settings.position==='bottom-right'){ctx.textAlign='right';draw(width-width*.045,height-height*.06);}
  else if(settings.position==='diagonal'){ctx.translate(width/2,height/2);ctx.rotate(-Math.PI/7);const distance=Math.max(size*3.5,height/3);for(let y=-distance;y<=distance;y+=distance)draw(0,y);}
  else draw(width/2,height/2);
  ctx.restore();
}
