function syncAdminSelection(){const finalize=document.querySelector('[data-action="admin-finalize-images"]');if(finalize)finalize.disabled=!state.adminSelection.size||state.adminBusy||state.adminDetail.finalDeliveryReady===false;document.querySelectorAll('[data-admin-image]').forEach(input=>input.checked=state.adminSelection.has(input.dataset.adminImage));const release=document.querySelector('[data-action="admin-release"]');if(release)release.disabled=!state.adminSelection.size||!state.adminReleaseUser;const revoke=document.querySelector('[data-action="admin-revoke-release"]');if(revoke)revoke.disabled=!state.adminSelection.size||!state.adminReleaseUser||state.adminDetail.imageControlsReady===false;const access=state.adminDetail.downloadAccess||{};document.querySelectorAll('[data-download-status]').forEach(node=>{node.hidden=!state.adminReleaseUser;const match=row=>row.userId===state.adminReleaseUser&&row.imageId===node.dataset.downloadStatus;node.textContent=tr((access.blocks||[]).some(match)?'downloadBlocked':(access.releases||[]).some(match)?'downloadReleased':'downloadNotReleased');});const counter=document.querySelector('#p-admin-selection-count');if(counter)counter.textContent=tr('selectedCount',{n:state.adminSelection.size});}
function onChange(event){
  if(event.target.name==='voucherSearch'||event.target.name==='voucherFilter'){if(event.target.name==='voucherSearch')state.voucherSearch=event.target.value;else state.voucherFilter=event.target.value;const results=document.querySelector('#p-voucher-results');if(results)results.innerHTML=voucherCardsHtml();}

  if(event.target.name==='finalReady'&&event.target.closest('#portal-upload-form'))event.target.form.querySelector('button[type=submit]').innerHTML=esc(tr(event.target.checked?'finalDirectUploadTitle':'finalProofUploadTitle'))+icon('plus');
  if(event.target.name==='finalFiles')prepareFinalBatch(event.target.files);
  if(event.target.matches('[data-final-mapping]')){const row=state.finalBatch?.rows[Number(event.target.dataset.finalMapping)];if(row&&!state.adminBusy&&!row.done){row.imageId=event.target.value;row.error=null;renderFinalBatchReview();document.querySelector(`[data-final-mapping="${event.target.dataset.finalMapping}"]`)?.focus();}}
  if(event.target.closest('#portal-delete-test-order-check,#portal-delete-test-order'))syncDeleteTestOrderConfirmation(event.target.form);
  if(event.target.name==='confirmName'&&event.target.closest('#portal-delete-gallery'))event.target.form.querySelector('button[type=submit]').disabled=event.target.value!==state.deleteGalleryTarget?.name;
  if(event.target.name==='packageId'&&event.target.closest('#portal-order-form'))updateCheckoutSummary();
  if(event.target.closest('#portal-gallery-settings'))updateDesignPreview();
  if(event.target.closest('#portal-studio-settings'))updateWatermarkSample();
  if(event.target.name==='studioSearch'||event.target.name==='studioDate'||event.target.name==='studioSort'){if(event.target.name==='studioSearch')state.adminSearch=event.target.value;if(event.target.name==='studioDate')state.adminDate=event.target.value;if(event.target.name==='studioSort')state.adminSort=event.target.value;const node=document.querySelector('#p-studio-results');if(node)node.innerHTML=state.adminTab==='galleries'?galleryCardsHtml():libraryCardsHtml();}
  const form=event.target.closest('form');
  if(event.target.name==='shootingType'&&form?.elements.pricingMode){form.elements.pricingMode.value=event.target.value==='school'?'images':'gallery';}
  if(event.target.name==='shootingType'){const retention=form?.querySelector('#p-create-retention');if(retention)retention.hidden=event.target.value!=='school';}
  if(['shootingType','pricingMode'].includes(event.target.name)){const hint=form?.querySelector('#p-create-pricing-hint');if(hint)hint.textContent=tr(form.elements.pricingMode.value==='images'?'schoolPricingIntro':'galleryPricingIntro');}
  if(event.target.matches('[data-admin-image]')){const id=event.target.dataset.adminImage;if(event.target.checked)state.adminSelection.add(id);else state.adminSelection.delete(id);syncAdminSelection();}
  if(event.target.id==='p-release-user'||event.target.id==='p-admin-access-user'){state.adminReleaseUser=event.target.value;renderAdminPhotoArea();}
  if(event.target.id==='p-admin-access-filter'){state.adminAccessFilter=event.target.value;renderAdminPhotoArea();}
  if(event.target.id==='p-admin-favourite-filter'){state.adminFavouriteFilter=event.target.value;renderAdminPhotoArea();}
  if(event.target.id==='p-admin-image-sort'&&event.target.value){const direction=event.target.value==='desc'?-1:1;state.adminOrderIds=orderedAdminImages().sort((a,b)=>direction*((a.title||a.id).localeCompare(b.title||b.id,locale,{numeric:true,sensitivity:'base'}))).map(image=>image.id);renderAdminPhotoArea();}
  if(event.target.id==='p-invoice-user')renderInvoiceStatus();
}
async function pollStudioActivity(){if(!state.admin||state.adminBusy||document.hidden)return;const userId=state.user?.id;try{const data=await api('/admin/activity');if(!state.admin||state.user?.id!==userId)return;const changed=Number(data.unreadCount)>state.adminUnread;state.adminUnread=data.unreadCount||0;const badge=document.querySelector('[data-studio-count]');if(badge){badge.textContent=state.adminUnread;badge.hidden=!state.adminUnread;}if(changed)toast(tr('newActivity'));}catch{/* The next refresh retries without interrupting an edit. */}}
setInterval(pollStudioActivity,60000);
app.addEventListener('input',event=>{if(event.target.name==='confirmName'||event.target.name==='studioSearch'||event.target.name==='voucherSearch'||event.target.closest('#portal-gallery-settings')||event.target.closest('#portal-studio-settings'))onChange(event);});
app.addEventListener('click',onAction);app.addEventListener('submit',onSubmit);app.addEventListener('change',onChange);
window.addEventListener('beforeunload',event=>{if(adminOrderDirty()||state.adminBusy){event.preventDefault();event.returnValue='';}});
async function initialise(){
  app.setAttribute('aria-busy','true');
  try{
    await loadSession();
    if(authToken){renderSetPassword();return;}
    if(!state.user){if(state.capabilities.configured===false){renderOffline();return;}renderLogin();return;}
    const paypalOrder=params.get('paypalOrder');
    if(paypalOrder){await api('/orders/'+encodeURIComponent(paypalOrder)+'/capture',{method:'POST'});params.delete('paypalOrder');params.delete('token');params.delete('PayerID');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);toast(tr('paymentProcessing'));}
    if(pendingGallery)await openGallery(pendingGallery);else await loadHome();openLinkedOrder();
  }catch(error){renderOffline();}
}
document.title=tr('title')+' | LiZa Memories Photography';
initialise();
